1	// Keyset-paginated article list (spec §1, Pagination). No OFFSET: a page costs the
2	// same wherever it is.
3	import type { Queryable } from "../db";
4	import { decodeCursor, encodeCursor } from "./cursor";
5	import {
6	  type ArticleFilters,
7	  buildFrom,
8	  buildWhere,
9	  filtersHash,
10	  Params,
11	  type RunKey,
12	} from "./filters";
13	
14	export const DEFAULT_LIMIT = 20;
15	export const MAX_LIMIT = 100;
16	
17	export type ArticleItem = {
18	  /** the brief's id */
19	  id: number;
20	  headline: string;
21	  source: string;
22	  language: string;
23	  published_at: string;
24	  /** present when the active run key has a row for this article */
25	  enrichment?: {
26	    status: string;
27	    summary: string | null;
28	    sentiment: string | null;
29	    tags: string[] | null;
30	  };
31	};
32	
33	export type ListRequest = {
34	  filters: ArticleFilters;
35	  runKey: RunKey;
36	  cursor?: string;
37	  limit?: number;
38	};
39	
40	type Row = {
41	  row_id: string;
42	  external_id: number;
43	  headline: string | null;
44	  source: string;
45	  language: string;
46	  published_at: Date;
47	  cursor_ts: string;
48	  status: string | null;
49	  summary: string | null;
50	  sentiment: string | null;
51	  tags: string[] | null;
52	};
53	
54	/** Throws InvalidCursorError for an unreadable cursor or one issued for other filters. */
55	export async function listArticles(
56	  db: Queryable,
57	  request: ListRequest,
58	): Promise<{ items: ArticleItem[]; nextCursor: string | null }> {
59	  const limit = Math.min(
60	    Math.max(Math.trunc(request.limit ?? DEFAULT_LIMIT) || DEFAULT_LIMIT, 1),
61	    MAX_LIMIT,
62	  );
63	  const hash = filtersHash(request.filters, request.runKey);
64	  const after =
65	    request.cursor === undefined ? null : decodeCursor(request.cursor, hash);
66	
67	  const params = new Params();
68	  const from = buildFrom(request.runKey, params);
69	  const conditions = [buildWhere(request.filters, params)];
70	  if (after) {
71	    const position = [
72	      params.add(after.ts) + "::timestamptz",
73	      params.add(after.id) + "::bigint",
74	    ];
75	    conditions.push("(a.published_at, a.id) < (" + position.join(", ") + ")");
76	  }
77	
78	  const sql = [
79	    "SELECT a.id AS row_id, a.external_id, a.headline, a.source, a.language, a.published_at,",
80	    `  to_char(a.published_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS cursor_ts,`,
81	    "  e.status, e.summary, e.sentiment, e.tags",
82	    from,
83	    "WHERE " + conditions.join(" AND "), // audit: sql-fragment — conditions are constants and $n placeholders from filters.ts
84	    "ORDER BY a.published_at DESC, a.id DESC",
85	    "LIMIT " + params.add(limit + 1), // audit: sql-fragment — the limit is a $n placeholder; one extra row tells whether a next page exists
86	  ].join("\n");
87	
88	  const { rows } = await db.query<Row>(sql, params.values);
89	  const page = rows.slice(0, limit);
90	  const last = page[page.length - 1];
91	
92	  return {
93	    items: page.map((row) => ({
94	      id: row.external_id,
95	      headline: row.headline ?? "",
96	      source: row.source,
97	      language: row.language,
98	      published_at: row.published_at.toISOString(),
99	      ...(row.status === null
100	        ? {}
101	        : {
102	            enrichment: {
103	              status: row.status,
104	              summary: row.summary,
105	              sentiment: row.sentiment,
106	              tags: row.tags,
107	            },
108	          }),
109	    })),
110	    nextCursor:
111	      rows.length > limit && last
112	        ? encodeCursor({ ts: last.cursor_ts, id: last.row_id }, hash)
113	        : null,
114	  };
115	}
116

