1	// Vitest global setup for the `integration` project only (see vitest.config.ts).
2	// Unit tests do not run this and pass with the database stopped.
3	import { Client } from "pg";
4	import { migrate } from "../scripts/migrate";
5	import { loadSampleArticles, seed } from "../scripts/seed";
6	import { TEST_DATABASE, testDatabaseUrl } from "./db-url";
7	
8	export default async function setup(): Promise<void> {
9	  const url = testDatabaseUrl();
10	
11	  // CREATE DATABASE cannot run inside the database it creates: connect to the
12	  // server's maintenance database with the same credentials.
13	  const admin = new URL(url);
14	  admin.pathname = "/postgres";
15	  const client = new Client({ connectionString: admin.toString() });
16	  try {
17	    await client.connect();
18	  } catch (cause) {
19	    throw new Error(
20	      "database not up: start it with `docker compose up -d db`",
21	      { cause },
22	    );
23	  }
24	  try {
25	    const found = await client.query(
26	      "SELECT 1 FROM pg_database WHERE datname = $1",
27	      [TEST_DATABASE],
28	    );
29	    if (found.rowCount === 0) {
30	      // The name is the constant above; CREATE DATABASE takes no parameter.
31	      await client.query("CREATE DATABASE media_test");
32	    }
33	  } finally {
34	    await client.end();
35	  }
36	
37	  // Migrations and seed, both idempotent, so the suite can run again and again on
38	  // the same media_test. Test files that write enrichment rows truncate that table
39	  // when they finish (plan §3, "Test database"); nothing writes `articles` but the seed.
40	  const db = new Client({ connectionString: url });
41	  await db.connect();
42	  try {
43	    await migrate(db);
44	    await seed(db, loadSampleArticles());
45	  } finally {
46	    await db.end();
47	  }
48	}
