  it("builds the AST as plain objects", () => {
    expect(parseQuery('oil AND NOT "supply chain" OR renew*')).toEqual({
      type: "or",
      left: {
        type: "and_not",
        left: { type: "term", text: "oil" },
        right: { type: "phrase", text: "supply chain" },
      },
      right: { type: "prefix", text: "renew" },
    });
  });

  it.each([
