    ["a'b:c&d*", "a'b:c&d*"],
    ["state-of-the-art", "state-of-the-art"],
    ["دبي", "دبي"],
    ["中国*", "中国*"],
    ["  oil  ", "oil"],
  ])("%s", (query, ast) => {
