// The boolean query as a tree (spec §2, Grammar). Leaves hold the user's text and
// nothing else does; the compiler sends each leaf's text as one `$n` parameter.

export type Leaf =
  /** a bare word */
  | { type: "term"; text: string }
  /** `word*`; `text` is the word without the star */
  | { type: "prefix"; text: string }
  /** `"some words"`; `text` is what is between the quotes */
  | { type: "phrase"; text: string };

export type Node =
  | Leaf
  | { type: "and"; left: Node; right: Node }
  | { type: "or"; left: Node; right: Node }
  /** `left AND NOT right` */
  | { type: "and_not"; left: Node; right: Node };

export function isLeaf(node: Node): node is Leaf {
  return (
    node.type === "term" || node.type === "prefix" || node.type === "phrase"
  );
}

/** A leaf as the user typed it. This is the text a warning carries. */
export function leafSource(leaf: Leaf): string {
  if (leaf.type === "prefix") return leaf.text + "*";
  if (leaf.type === "phrase") return '"' + leaf.text + '"';
  return leaf.text;
}

/** Every leaf, left to right. */
export function leavesOf(node: Node): Leaf[] {
  return isLeaf(node)
    ? [node]
    : [...leavesOf(node.left), ...leavesOf(node.right)];
}

const LABEL = { and: "AND", or: "OR", and_not: "AND-NOT" } as const;

/** The tree on one line, for tests and `npm run search:debug`: `(AND a (OR b c))`. */
export function formatAst(node: Node): string {
  if (isLeaf(node)) return leafSource(node);
  return `(${LABEL[node.type]} ${formatAst(node.left)} ${formatAst(node.right)})`;
}

// Query text → tokens (spec §2, Grammar):
//
//   PHRASE := '"' [^"]+ '"'
//   PREFIX := TERM '*'
//   TERM   := [^\s()"*]+      -- but not exactly AND / OR / NOT
//
// Operators are case-sensitive (R7): `AND` is an operator, `and` is a term.
// A term, prefix or phrase with no letter or digit is rejected here (deviation 3):
// it has no lexeme under either text-search config, so it could never match.

/** A query the grammar or the limits reject. Maps to HTTP 400 `invalid_query`. */
export class InvalidQueryError extends Error {
  readonly code = "invalid_query";
  constructor(message: string) {
    super(message);
    this.name = "InvalidQueryError";
  }
}

export type Token =
  | { type: "lparen" | "rparen" | "and" | "or" | "not" }
  | { type: "term" | "prefix" | "phrase"; text: string };

const OPERATORS: Record<string, "and" | "or" | "not"> = {
  AND: "and",
  OR: "or",
  NOT: "not",
};
const WORD = /[^\s()"*]+/y;
const LETTER_OR_DIGIT = /[\p{L}\p{N}]/u;

/** Quotes a token for an error message, shortened so a message stays short. */
export function shown(text: string): string {
  const chars = [...text];
  return (
    "'" + (chars.length > 40 ? chars.slice(0, 40).join("") + "…" : text) + "'"
  );
}

function requireLetterOrDigit(text: string, source: string): void {
  if (!LETTER_OR_DIGIT.test(text)) {
    throw new InvalidQueryError(
      `${shown(source)} has no letter or digit to search for`,
    );
  }
}

export function tokenize(query: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < query.length) {
    const char = query[i]!;
    if (/\s/.test(char)) {
      i += 1;
    } else if (char === "(") {
      tokens.push({ type: "lparen" });
      i += 1;
    } else if (char === ")") {
      tokens.push({ type: "rparen" });
      i += 1;
    } else if (char === '"') {
      const end = query.indexOf('"', i + 1);
      if (end === -1) {
        throw new InvalidQueryError("a quote is opened but never closed");
      }
      const text = query.slice(i + 1, end);
      if (text === "") throw new InvalidQueryError('"" is an empty phrase');
      requireLetterOrDigit(text, '"' + text + '"');
      tokens.push({ type: "phrase", text });
      i = end + 1;
    } else if (char === "*") {
      throw new InvalidQueryError(
        "'*' is only allowed at the end of a term, as in renew*",
      );
    } else {
      WORD.lastIndex = i;
      const text = WORD.exec(query)![0];
      i += text.length;
      const star = query[i] === "*";
      const operator = Object.hasOwn(OPERATORS, text)
        ? OPERATORS[text]
        : undefined;
      if (operator && star) {
        throw new InvalidQueryError(
          `'*' cannot follow the operator ${text}; operators are upper case, terms are not`,
        );
      }
      if (operator) {
        tokens.push({ type: operator });
      } else if (star) {
        requireLetterOrDigit(text, text + "*");
        tokens.push({ type: "prefix", text });
        i += 1;
      } else {
        requireLetterOrDigit(text, text);
        tokens.push({ type: "term", text });
      }
    }
  }
  return tokens;
}

// Tokens → AST, by recursive descent over the grammar of spec §2:
//
//   query := or
//   or    := and ( "OR" and )*
//   and   := unary ( ( "AND" | "AND" "NOT" )? unary )*     -- adjacency = AND
//   unary := "(" or ")" | PHRASE | PREFIX | TERM
//
// AND and AND NOT bind tighter than OR; all three are left-associative.
import type { Node } from "./ast";
import { InvalidQueryError, shown, type Token, tokenize } from "./lexer";

export { InvalidQueryError };

/** S4. Length is counted in characters, before anything is trimmed. */
export const MAX_LENGTH = 500;
/** S4, "≤ 32 terms": terms, prefixes and phrases; a phrase counts once. */
export const MAX_LEAVES = 32;
/** S4: depth of nested brackets. */
export const MAX_DEPTH = 8;

const NAME = { and: "AND", or: "OR", not: "NOT" } as const;

function describe(token: Token | undefined): string {
  if (!token) return "the end of the query";
  switch (token.type) {
    case "lparen":
      return "'('";
    case "rparen":
      return "')'";
    case "and":
    case "or":
    case "not":
      return NAME[token.type];
    case "term":
      return shown(token.text);
    case "prefix":
      return shown(token.text + "*");
    case "phrase":
      return shown('"' + token.text + '"');
  }
}

export function parseQuery(query: string): Node {
  if ([...query].length > MAX_LENGTH) {
    throw new InvalidQueryError(
      `the query is longer than ${MAX_LENGTH} characters`,
    );
  }
  const tokens = tokenize(query);
  if (tokens.length === 0) throw new InvalidQueryError("the query is empty");

  let position = 0;
  let depth = 0;
  let leaves = 0;
  const peek = (): Token | undefined => tokens[position];

  function unary(): Node {
    const token = peek();
    if (token?.type === "lparen") {
      position += 1;
      depth += 1;
      if (depth > MAX_DEPTH) {
        throw new InvalidQueryError(
          `brackets are nested more than ${MAX_DEPTH} deep`,
        );
      }
      const inner = or();
      if (peek()?.type !== "rparen") {
        throw new InvalidQueryError(
          `a bracket is opened but never closed: expected ')' before ${describe(peek())}`,
        );
      }
      position += 1;
      depth -= 1;
      return inner;
    }
    if (
      token?.type === "term" ||
      token?.type === "prefix" ||
      token?.type === "phrase"
    ) {
      position += 1;
      leaves += 1;
      if (leaves > MAX_LEAVES) {
        throw new InvalidQueryError(
          `the query has more than ${MAX_LEAVES} terms`,
        );
      }
      return { type: token.type, text: token.text };
    }
    if (token?.type === "not") {
      throw new InvalidQueryError(
        "NOT is only allowed after AND, as in a AND NOT b",
      );
    }
    const before = tokens[position - 1];
    throw new InvalidQueryError(
      before
        ? `expected a term after ${describe(before)}, found ${describe(token)}`
        : `expected a term, found ${describe(token)}`,
    );
  }

  function and(): Node {
    let left = unary();
    for (;;) {
      const token = peek();
      if (token?.type === "and") {
        position += 1;
        if (peek()?.type === "not") {
          position += 1;
          left = { type: "and_not", left, right: unary() };
        } else {
          left = { type: "and", left, right: unary() };
        }
      } else if (
        token?.type === "lparen" ||
        token?.type === "term" ||
        token?.type === "prefix" ||
        token?.type === "phrase"
      ) {
        left = { type: "and", left, right: unary() };
      } else {
        return left;
      }
    }
  }

  function or(): Node {
    let left = and();
    while (peek()?.type === "or") {
      position += 1;
      left = { type: "or", left, right: and() };
    }
    return left;
  }

  const root = or();
  const rest = peek();
  if (rest?.type === "rparen") {
    throw new InvalidQueryError("a bracket is closed but was never opened");
  }
  if (rest?.type === "not") {
    throw new InvalidQueryError(
      "NOT is only allowed after AND, as in a AND NOT b",
    );
  }
  if (rest) {
    throw new InvalidQueryError(`unexpected ${describe(rest)}`);
  }
  return root;
}

// The empty-leaf pre-query (spec §2, "Empty-leaf rule"). Only Postgres knows each
// config's stop list, so one query asks it which leaves produce an empty tsquery
// under `english` and under `simple`. The compiler removes those leaves from that
// config's fragment; without this, `tsv @@ ''::tsquery` is false and `oil and gas`
// would match nothing with no explanation, and `the*` would be a tsquery syntax
// error (a 500).
//
// The SQL is one constant string. The leaves travel as two array parameters.
import type { Queryable } from "../db";
import type { Leaf } from "./ast";

/** Positions, in `leavesOf` order, of the leaves that are empty under each config. */
export type EmptyLeaves = { english: Set<number>; simple: Set<number> };

// A prefix is checked through plainto_tsquery, the function its compiled form
// starts from: if that is empty there is nothing to append `:*` to.
const SQL = `
  SELECT
    l.i::int - 1 AS position,
    numnode(CASE WHEN l.kind = 'phrase'
              THEN phraseto_tsquery('english', l.leaf)
              ELSE plainto_tsquery('english', l.leaf) END) = 0 AS english_empty,
    numnode(CASE WHEN l.kind = 'phrase'
              THEN phraseto_tsquery('simple', l.leaf)
              ELSE plainto_tsquery('simple', l.leaf) END) = 0 AS simple_empty
  FROM unnest($1::text[], $2::text[]) WITH ORDINALITY AS l (leaf, kind, i)
  ORDER BY l.i`;

type Row = { position: number; english_empty: boolean; simple_empty: boolean };

export async function findEmptyLeaves(
  db: Queryable,
  leaves: Leaf[],
): Promise<EmptyLeaves> {
  const { rows } = await db.query<Row>(SQL, [
    leaves.map((leaf) => leaf.text),
    leaves.map((leaf) => leaf.type),
  ]);
  const empty: EmptyLeaves = { english: new Set(), simple: new Set() };
  for (const row of rows) {
    if (row.english_empty) empty.english.add(row.position);
    if (row.simple_empty) empty.simple.add(row.position);
  }
  return empty;
}

