// Runs `npm run search:debug -- <query>` for every case in the expectations file
// (no shell, so no quoting), prints the raw output, then a comparison table.
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

const root = process.argv[2];
const { cases } = JSON.parse(
  readFileSync(root + "/tests/fixtures/search-expectations.json", "utf8"),
);
const rows = [];
for (const c of cases) {
  let out;
  try {
    out = execFileSync(
      "npx",
      ["tsx", "scripts/search-debug.ts", c.query],
      { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
    );
  } catch (e) {
    out = "error:    internal — " + String(e.stderr || e.message).split("\n")[0];
  }
  console.log(`--- ${c.id}\n${out}`);
  const line = (key) =>
    out.split("\n").find((l) => l.startsWith(key))?.slice(key.length).trim();
